7	import stripAnsi from 'strip-ansi';
8	
9	/**
10	 * Safely replaces text with literal strings, avoiding ECMAScript GetSubstitution issues.
11	 * Escapes $ characters to prevent template interpretation.
12	 */
13	export function safeLiteralReplace(
14	  str: string,
15	  oldString: string,
16	  newString: string,
17	): string {
18	  if (oldString === '' || !str.includes(oldString)) {
19	    return str;
20	  }
21	
22	  if (!newString.includes('$')) {
23	    return str.replaceAll(oldString, newString);
24	  }
25	
26	  const escapedNewString = newString.replaceAll('$', '$$$$');
27	  return str.replaceAll(oldString, escapedNewString);
28	}
