99	/**
100	 * Truncates a string to a maximum length, appending a suffix if truncated.
101	 * @param str The string to truncate.
102	 * @param maxLength The maximum length of the string.
103	 * @param suffix The suffix to append if truncated (default: '...[TRUNCATED]').
104	 * @returns The truncated string.
105	 */
106	export function truncateString(
107	  str: string,
108	  maxLength: number,
109	  suffix = '...[TRUNCATED]',
110	): string {
111	  if (str.length <= maxLength) {
112	    return str;
113	  }
114	
115	  // This regex matches a "Grapheme Cluster" manually:
116	  // 1. A surrogate pair OR a single character...
117	  // 2. Followed by any number of "Combining Marks" (\p{M})
118	  // 'u' flag is required for Unicode property escapes
119	  const graphemeRegex = /(?:[\uD800-\uDBFF][\uDC00-\uDFFF]|.)\p{M}*/gu;
120	
121	  let truncatedStr = '';
122	  let match: RegExpExecArray | null;
123	
124	  while ((match = graphemeRegex.exec(str)) !== null) {
125	    const segment = match[0];
126	
127	    // If adding the whole cluster (base char + accent) exceeds maxLength, stop.
128	    if (truncatedStr.length + segment.length > maxLength) {
129	      break;
130	    }
131	
132	    truncatedStr += segment;
133	    if (truncatedStr.length >= maxLength) break;
134	  }
135	
136	  // Final safety check for dangling high surrogates
137	  if (truncatedStr.length > 0) {
138	    const lastCode = truncatedStr.charCodeAt(truncatedStr.length - 1);
139	    if (lastCode >= 0xd800 && lastCode <= 0xdbff) {
140	      truncatedStr = truncatedStr.slice(0, -1);
141	    }
142	  }
143	
144	  return truncatedStr + suffix;
145	}
