41	const URL_FETCH_TIMEOUT_MS = 10000;
42	const MAX_CONTENT_LENGTH = 250000;
43	const MAX_EXPERIMENTAL_FETCH_SIZE = 10 * 1024 * 1024; // 10MB
44	const USER_AGENT =
