46	const TRUNCATION_WARNING = '\n\n... [Content truncated due to size limit] ...';
47	
48	// Rate limiting configuration
49	const RATE_LIMIT_WINDOW_MS = 60000; // 1 minute
50	const MAX_REQUESTS_PER_WINDOW = 10;
51	const hostRequestHistory = new LRUCache<string, number[]>(1000);
52	
53	function checkRateLimit(url: string): {
54	  allowed: boolean;
55	  waitTimeMs?: number;
56	} {
57	  try {
58	    const hostname = new URL(url).hostname;
59	    const now = Date.now();
60	    const windowStart = now - RATE_LIMIT_WINDOW_MS;
61	
62	    let history = hostRequestHistory.get(hostname) || [];
63	    // Clean up old timestamps
64	    history = history.filter((timestamp) => timestamp > windowStart);
65	
66	    if (history.length >= MAX_REQUESTS_PER_WINDOW) {
67	      // Calculate wait time based on the oldest timestamp in the current window
68	      const oldestTimestamp = history[0];
69	      const waitTimeMs = oldestTimestamp + RATE_LIMIT_WINDOW_MS - now;
70	      hostRequestHistory.set(hostname, history); // Update cleaned history
71	      return { allowed: false, waitTimeMs: Math.max(0, waitTimeMs) };
72	    }
73	
74	    history.push(now);
75	    hostRequestHistory.set(hostname, history);
76	    return { allowed: true };
77	  } catch {
78	    // If URL parsing fails, we fallback to allowed (should be caught by parsePrompt anyway)
79	    return { allowed: true };
80	  }
81	}
