83	/**
84	 * Normalizes a URL by converting hostname to lowercase, removing trailing slashes,
85	 * and removing default ports.
86	 */
87	export function normalizeUrl(urlStr: string): string {
88	  try {
89	    const url = new URL(urlStr);
90	    url.hostname = url.hostname.toLowerCase();
91	    // Remove trailing slash if present in pathname (except for root '/')
92	    if (url.pathname.endsWith('/') && url.pathname.length > 1) {
93	      url.pathname = url.pathname.slice(0, -1);
94	    }
95	    // Remove default ports
96	    if (
97	      (url.protocol === 'http:' && url.port === '80') ||
98	      (url.protocol === 'https:' && url.port === '443')
99	    ) {
100	      url.port = '';
101	    }
102	    return url.href;
103	  } catch {
104	    return urlStr;
105	  }
106	}
