149	export function convertGithubUrlToRaw(urlStr: string): string {
150	  try {
151	    const url = new URL(urlStr);
152	    if (url.hostname === 'github.com' && url.pathname.includes('/blob/')) {
153	      url.hostname = 'raw.githubusercontent.com';
154	      url.pathname = url.pathname.replace(/^\/([^/]+\/[^/]+)\/blob\//, '/$1/');
155	      return url.href;
156	    }
157	  } catch {
158	    // Ignore invalid URLs
159	  }
160	  return urlStr;
161	}
