+/**
+ * Wraps content originating from external tools in `<untrusted_context>` tags
+ * so the model can distinguish untrusted data from trusted instructions.
+ *
+ * Any occurrence of the closing tag within the input is escaped to prevent the
+ * content from prematurely closing the wrapper (a prompt-injection vector).
+ *
+ * @param content The untrusted content to wrap.
+ * @returns The content wrapped in `<untrusted_context>` tags.
+ */
+export function wrapUntrusted(content: string): string {
+  const escaped = content.replaceAll(
+    '</untrusted_context>',
+    '&lt;/untrusted_context&gt;',
+  );
+  return `<untrusted_context>\n${escaped}\n</untrusted_context>`;
+}
